import test from 'node:test';
import assert from 'node:assert/strict';
import { normalizeId, mergeCustomers } from '../src/customers.js';

test('normalizeId trims and uppercases', () => {
  assert.equal(normalizeId('  abc  '), 'ABC');
  assert.equal(normalizeId('ABC'), 'ABC');
  assert.equal(normalizeId('aBc'), 'ABC');
});

test('normalizeId handles null and undefined', () => {
  assert.equal(normalizeId(null), '');
  assert.equal(normalizeId(undefined), '');
});

test('mergeCustomers removes fromId and updates invoices', () => {
  const customers = [
    { id: 'CUST1', name: 'Alice', email: 'alice@example.com', country: 'US', tier: 'gold' },
    { id: 'CUST2', name: 'Bob', email: 'bob@example.com', country: 'UK', tier: 'silver' },
  ];

  const invoices = [
    { customerId: 'CUST1', number: 'INV001', status: 'issued', lines: [] },
    { customerId: 'CUST2', number: 'INV002', status: 'issued', lines: [] },
    { customerId: 'CUST1', number: 'INV003', status: 'draft', lines: [] },
  ];

  const result = mergeCustomers(customers, invoices, 'CUST1', 'CUST2');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.customers[0].id, 'CUST2');
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].customerId, 'CUST2');
  assert.equal(result.value.invoices[1].customerId, 'CUST2');
  assert.equal(result.value.invoices[2].customerId, 'CUST2');
});

test('mergeCustomers normalizes IDs', () => {
  const customers = [
    { id: 'CUST1', name: 'Alice', email: 'alice@example.com', country: 'US', tier: 'gold' },
    { id: 'CUST2', name: 'Bob', email: 'bob@example.com', country: 'UK', tier: 'silver' },
  ];

  const invoices = [
    { customerId: 'CUST1', number: 'INV001', status: 'issued', lines: [] },
  ];

  const result = mergeCustomers(customers, invoices, '  cust1  ', 'CuSt2');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.invoices[0].customerId, 'CUST2');
});

test('mergeCustomers returns SAME_CUSTOMER if IDs are the same', () => {
  const customers = [
    { id: 'CUST1', name: 'Alice', email: 'alice@example.com', country: 'US', tier: 'gold' },
  ];

  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'CUST1', 'CUST1');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'SAME_CUSTOMER');
});

test('mergeCustomers returns SAME_CUSTOMER if normalized IDs are the same', () => {
  const customers = [
    { id: 'CUST1', name: 'Alice', email: 'alice@example.com', country: 'US', tier: 'gold' },
